 const defaults={theme:'Default',accent:'#95ff50',secondary:'#7c5cff',background:'#08070d',episodes:'carousel',details:'page',logos:true,trailers:true,spoilers:false,motion:true,autoplay:true,autoSkip:false,febbox:'',seek:10,subFont:'Inter',subSize:100,subColor:'#ffffff',subBackground:true,sourceRanking:'auto',serverOrder:providers.map(p=>p.id),hiddenControls:[],controlLayout:null};
