 function apply(){document.documentElement.dataset.theme=settings.theme.toLowerCase();document.documentElement.dataset.motion=settings.motion?'on':'off';applyTheme(settings);document.body.classList.toggle('text-logos',!settings.logos);document.body.classList.toggle('spoiler-free',settings.spoilers);document.body.classList.toggle('episodes-grid',settings.episodes==='grid');prefs.motion=settings.motion;write('bogart.settings.v1',prefs);streamPlayer.controlSettings=settings;}
 window.addEventListener('storage',event=>{if(event.key==='outlaw.settings.v1'&&event.newValue){try{const incoming=JSON.parse(event.newValue);if(incoming&&typeof incoming==='object'){Object.assign(settings,incoming);apply()}}catch{}}});
