 function openDialog(title,content,className=''){closeDialog();previousModalFocus=document.activeElement;modal=document.createElement('dialog');modal.className='outlaw-dialog '+className;modal.innerHTML='<header><h2>'+esc(title)+'</h2><button data-dismiss aria-label="Close '+esc(title)+'">×</button></header><div class="outlaw-dialog-body">'+content+'</div>';document.body.append(modal);modal.querySelector('[data-dismiss]').onclick=()=>modal.close();const ownedDialog=modal,returnFocus=previousModalFocus;modal.addEventListener('close',()=>{if(modal===ownedDialog)modal=null;ownedDialog.remove();returnFocus?.isConnected&&returnFocus.focus()},{once:true});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});modal.showModal();return modal}
 function closeDialog(){const d=modal;if(d?.open){modal=null;d.close();d.remove()}}
