 async function renderDiscoverLists(){const token=++routeId;document.title='Discover Lists · Spex';app.innerHTML='<section class="browse-page library-page reference-lists"><h1>'+uiIcon('compass')+'Discover</h1><p class="public-list-total" role="status">Loading public lists…</p><div class="search-field public-list-search">'+uiIcon('search')+'<input type="search" aria-label="Search public list names" placeholder="Search public list names"></div><div id="discoverLists"></div></section>';const host=app.querySelector('#discoverLists'),input=app.querySelector('.public-list-search input');let request=0,timer;const load=async()=>{const current=++request;try{const data=await community.api('/lists'+(input.value.trim()?'?q='+encodeURIComponent(input.value.trim()):''));if(token!==routeId||current!==request||!host.isConnected)return;app.querySelector('.public-list-total').textContent=(data.items?.length||0)+' public lists from the community';host.innerHTML=data.items?.length?'<div class="list-cover-grid">'+data.items.map(l=>'<a class="list-cover" href="/list/'+esc(l.id)+'"><div>'+(l.items||[]).slice(0,4).map(t=>t.poster?'<img src="'+esc(t.poster)+'" alt="">':'').join('')+'</div><h2>'+esc(l.name)+'</h2><p>by '+esc(l.author)+' · '+(l.items?.length||0)+' titles</p></a>').join('')+'</div>':'<div class="lists-empty">'+uiIcon('list')+'<h2>'+(input.value.trim()?'No matching lists':'No public lists yet')+'</h2><p>'+(input.value.trim()?'Try another list name.':'Published lists will appear here.')+'</p></div>';normalizeLinks()}catch(e){if(current===request&&host.isConnected){host.innerHTML='<p>'+esc(e.message)+'</p><button class="subtle-pill">Try again</button>';host.querySelector('button').onclick=load}}};input.oninput=()=>{clearTimeout(timer);timer=setTimeout(load,250)};await load()}

